-- OFFLINE PG17 SYNTHETIC ONLY. Additive application-reference lane, not a
-- production migration. No native object versions, old proof upgrades or new
-- processing permission ledger. The original runtime functions remain closed.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_content_manifest') IS NULL OR to_regnamespace('design_canonical_verification') IS NULL OR to_regnamespace('design_content_pipeline') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PIPELINE_FIXTURE_REQUIRED';END IF;END$$;
CREATE SCHEMA design_content_pipeline AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_content_pipeline FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_content_pipeline TO design_identity_runtime,design_normalization_runtime,design_normalization_processing_issuer,design_canonical_authorizer,design_canonical_verifier,design_content_storage_issuer,design_content_capability,design_managed_image_capability;
GRANT CREATE ON SCHEMA design_content_pipeline TO design_content_capability,design_managed_image_capability;
CREATE TABLE design_content_pipeline.source_bindings(write_id text PRIMARY KEY REFERENCES design_content_manifest.reservations,source_ref jsonb NOT NULL UNIQUE,binding jsonb NOT NULL,intent_digest text NOT NULL);
ALTER TABLE design_content_pipeline.source_bindings OWNER TO design_identity_owner;
ALTER TABLE design_content_pipeline.source_bindings ENABLE ROW LEVEL SECURITY;
ALTER TABLE design_content_pipeline.source_bindings FORCE ROW LEVEL SECURITY;
CREATE POLICY capability_only ON design_content_pipeline.source_bindings TO design_content_capability USING(true) WITH CHECK(true);
GRANT SELECT,INSERT ON design_content_pipeline.source_bindings TO design_content_capability;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON design_content_pipeline.source_bindings FOR EACH ROW EXECUTE FUNCTION design_content_manifest.immutable_row();
-- Each public fixed function enforces its session_user before this helper.
CREATE FUNCTION design_content_pipeline.resolve(a_token text,a_scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN
 IF (a_token IS NULL OR length(a_token) NOT BETWEEN 32 AND 200 OR a_token~'[[:space:][:cntrl:]]') IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));r:=design_identity.resolve_hash(encode(sha256(convert_to(a_token,'UTF8')),'hex'),a_scope);
 IF ((r->>'expiresAt')::timestamptz<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED' USING ERRCODE='42501';END IF;RETURN r->'authority';END$$;
CREATE FUNCTION design_content_pipeline.ref(m jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT jsonb_build_object('manifestId',m->'manifestId','revision',m->'revision','digest',design_content_manifest.digest(m))$$;
CREATE FUNCTION design_content_pipeline.validate_ref(r jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$BEGIN
 IF (NOT design_content_manifest.exact(r,ARRAY['manifestId','revision','digest']) OR jsonb_typeof(r->'manifestId') IS DISTINCT FROM 'string' OR r->>'manifestId'!~'^content-manifest-[a-f0-9]{64}$' OR jsonb_typeof(r->'digest') IS DISTINCT FROM 'string' OR r->>'digest'!~'^[a-f0-9]{64}$' OR jsonb_typeof(r->'revision') IS DISTINCT FROM 'number' OR r->>'revision'!~'^[1-9][0-9]{0,3}$' OR (r->>'revision')::int>1000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PIPELINE_INVALID' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.make_source_binding(a jsonb,i jsonb,media text,st text,ang text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$BEGIN
 IF (jsonb_typeof(to_jsonb(media)) IS DISTINCT FROM 'string' OR media!~'^[A-Za-z0-9_-]{1,100}$' OR st NOT IN ('before','after') OR ang NOT IN ('front','back','left','right') OR st IS NULL OR ang IS NULL OR i->>'role' IS DISTINCT FROM 'source' OR i->'content'->>'mime' NOT IN ('image/jpeg','image/webp') OR i->'assetId' IS DISTINCT FROM to_jsonb(media)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PIPELINE_INVALID' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('schemaVersion','design-application-image-source-v1','authority',a,'requestId',i->'requestId','mediaId',media,'stage',st,'angle',ang,'source',design_content_pipeline.ref(design_content_manifest.expected_manifest(i)));END$$;
CREATE FUNCTION design_content_pipeline.prepare_upload(token text,scope jsonb,rid text,media text,st text,ang text,content jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;i jsonb;b jsonb;c design_content_manifest.config;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);SELECT * INTO STRICT c FROM design_content_manifest.config WHERE singleton;
 i:=jsonb_build_object('schemaVersion','application-content-write-intent-v1','authority',a,'requestId',rid,'assetId',media,'role','source','expectedRevision',0,'expectedManifestDigest',null,'content',content,'target',jsonb_build_object('projectOrigin',c.project_origin,'bucket',c.bucket,'key','managed-content/v1/'||design_content_manifest.digest(a->'scope')||'/'||design_content_manifest.owner_key(a)||'/'||design_content_manifest.write_id(a,rid)||'/'||(content->>'sha256')),'ancestry','{"source":null,"parent":null}'::jsonb,'processing',null,'private',true,'storageSemantics','application_create_only_no_native_versions');
 PERFORM design_content_manifest.check_intent(a,i);b:=design_content_pipeline.make_source_binding(a,i,media,st,ang);PERFORM design_content_manifest.check_intent(design_content_pipeline.resolve(token,scope),i);RETURN jsonb_build_object('intent',i,'sourceBinding',b);END$$;
CREATE FUNCTION design_content_pipeline.reserve_upload(token text,scope jsonb,i jsonb,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_content_manifest.permissions;r design_content_manifest.reservations;old design_content_pipeline.source_bindings;wid text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);p:=design_content_manifest.permission(a,i);
 IF b IS DISTINCT FROM design_content_pipeline.make_source_binding(a,i,b->>'mediaId',b->>'stage',b->>'angle') OR i->'expectedRevision' IS DISTINCT FROM '0'::jsonb THEN RAISE EXCEPTION 'CONTENT_PIPELINE_BINDING' USING ERRCODE='42501';END IF;
 wid:=design_content_manifest.write_id(a,i->>'requestId');SELECT * INTO r FROM design_content_manifest.reservations x WHERE x.write_id=wid;
 IF FOUND THEN SELECT * INTO STRICT old FROM design_content_pipeline.source_bindings x WHERE x.write_id=wid;IF r.intent IS DISTINCT FROM i OR old.binding IS DISTINCT FROM b THEN RAISE EXCEPTION 'CONTENT_PIPELINE_CONFLICT' USING ERRCODE='42501';END IF;
 ELSE PERFORM design_content_manifest.head_ok(i);IF EXISTS(SELECT 1 FROM design_content_manifest.reservations x WHERE x.manifest_id=design_content_manifest.manifest_id(i) AND x.expected_revision=0 AND NOT EXISTS(SELECT 1 FROM design_content_manifest.terminations t WHERE t.write_id=x.write_id)) THEN RAISE EXCEPTION 'CONTENT_HEAD_RESERVED' USING ERRCODE='42501';END IF;
 INSERT INTO design_content_manifest.reservations VALUES(wid,design_content_manifest.manifest_id(i),0,i,design_content_manifest.digest(i),p.id);
 INSERT INTO design_content_pipeline.source_bindings VALUES(wid,b->'source',b,design_content_manifest.digest(i));END IF;
 RETURN design_content_manifest.context(design_content_pipeline.resolve(token,scope),i->>'requestId');END$$;
CREATE FUNCTION design_content_pipeline.check_source(a jsonb,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE m design_content_manifest.manifests;b design_content_pipeline.source_bindings;ctx jsonb;BEGIN
 PERFORM design_content_pipeline.validate_ref(r);SELECT * INTO STRICT m FROM design_content_manifest.manifests x WHERE x.manifest_id=r->>'manifestId' AND x.revision=(r->>'revision')::int;
 IF design_content_pipeline.ref(m.record) IS DISTINCT FROM r OR m.digest IS DISTINCT FROM r->>'digest' OR m.record->'authority' IS DISTINCT FROM a OR m.record->>'role' IS DISTINCT FROM 'source' THEN RAISE EXCEPTION 'CONTENT_PIPELINE_BINDING' USING ERRCODE='42501';END IF;
 ctx:=design_content_manifest.context(a,m.record->>'requestId','read');SELECT * INTO STRICT b FROM design_content_pipeline.source_bindings x WHERE x.write_id=m.write_id;
 IF ctx->'manifest' IS DISTINCT FROM m.record OR b.source_ref IS DISTINCT FROM r OR b.intent_digest IS DISTINCT FROM ctx->'manifest'->>'intentDigest' OR b.binding IS DISTINCT FROM design_content_pipeline.make_source_binding(a,ctx->'intent',b.binding->>'mediaId',b.binding->>'stage',b.binding->>'angle') THEN RAISE EXCEPTION 'CONTENT_PIPELINE_BINDING' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('sourceBinding',b.binding,'sourceManifest',m.record);END$$;
CREATE FUNCTION design_content_pipeline.read_source(token text,scope jsonb,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;v jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);v:=design_content_pipeline.check_source(a,r);IF v IS DISTINCT FROM design_content_pipeline.check_source(design_content_pipeline.resolve(token,scope),r) THEN RAISE EXCEPTION 'CONTENT_PIPELINE_CHANGED';END IF;RETURN v;END$$;
CREATE FUNCTION design_content_pipeline.upload_status(token text,scope jsonb,rid text,media text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;b design_content_pipeline.source_bindings;r design_content_manifest.reservations;m design_content_manifest.manifests;st text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' OR rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$' OR media IS NULL OR media!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED' USING ERRCODE='42501';END IF;
 a:=design_content_pipeline.resolve(token,scope);SELECT * INTO b FROM design_content_pipeline.source_bindings x WHERE x.write_id=design_content_manifest.write_id(a,rid);IF NOT FOUND THEN IF design_content_pipeline.resolve(token,scope) IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_PIPELINE_CHANGED';END IF;RETURN NULL;END IF;
 SELECT * INTO STRICT r FROM design_content_manifest.reservations x WHERE x.write_id=b.write_id;PERFORM design_content_manifest.check_intent(a,r.intent);
 IF b.binding IS DISTINCT FROM design_content_pipeline.make_source_binding(a,r.intent,media,b.binding->>'stage',b.binding->>'angle') OR b.intent_digest IS DISTINCT FROM design_content_manifest.digest(r.intent) THEN RAISE EXCEPTION 'CONTENT_PIPELINE_BINDING' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM design_content_manifest.manifests x WHERE x.write_id=b.write_id;
 st:=CASE WHEN EXISTS(SELECT 1 FROM design_content_manifest.terminations x WHERE x.write_id=b.write_id) THEN 'terminated' WHEN m.write_id IS NOT NULL THEN 'published' WHEN EXISTS(SELECT 1 FROM design_content_manifest.claims x WHERE x.write_id=b.write_id) THEN 'claimed' ELSE 'reserved' END;
 IF m.write_id IS NOT NULL AND (m.record IS DISTINCT FROM design_content_manifest.expected_manifest(r.intent) OR design_content_pipeline.ref(m.record) IS DISTINCT FROM b.source_ref) THEN RAISE EXCEPTION 'CONTENT_PIPELINE_BINDING' USING ERRCODE='42501';END IF;
 IF design_content_pipeline.resolve(token,scope) IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_PIPELINE_CHANGED';END IF;RETURN jsonb_build_object('sourceBinding',b.binding,'state',st,'manifest',m.record);END$$;
-- Remaining v2 processing/derived/verification fixed functions are additive below.
CREATE TABLE design_content_pipeline.config(singleton boolean PRIMARY KEY CHECK(singleton),policy jsonb NOT NULL,verifier jsonb NOT NULL);
ALTER TABLE design_content_pipeline.config OWNER TO design_identity_owner;
ALTER TABLE design_content_pipeline.config ENABLE ROW LEVEL SECURITY;
ALTER TABLE design_content_pipeline.config FORCE ROW LEVEL SECURITY;
CREATE POLICY capability_only ON design_content_pipeline.config TO design_managed_image_capability USING(true);
GRANT SELECT ON design_content_pipeline.config TO design_managed_image_capability;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON design_content_pipeline.config FOR EACH ROW EXECUTE FUNCTION design_content_manifest.immutable_row();
CREATE FUNCTION design_content_pipeline.make_processing(a jsonb,sref jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE s jsonb;c design_content_pipeline.config;BEGIN
 IF rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_INVALID' USING ERRCODE='42501';END IF;s:=design_content_pipeline.check_source(a,sref);SELECT * INTO STRICT c FROM design_content_pipeline.config WHERE singleton;
 IF (s->'sourceManifest'->>'requestId' IS NOT DISTINCT FROM rid OR s->'sourceManifest'->'content'->>'mime' NOT IN ('image/jpeg','image/webp')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PROCESSING_INVALID' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('schemaVersion','design-normalization-processing-intent-v2','purpose','private_application_direct_png_normalization','requestId',rid,'authority',a,'sourceBinding',s->'sourceBinding','sourceManifest',s->'sourceManifest','policy',c.policy,'maximumOutputBytes',262144,'maximumAttempts',1);END$$;
-- Keep the full live binding check; void callers need not derive a discarded hash.
CREATE FUNCTION design_content_pipeline.assert_processing_binding(a jsonb,i jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF i IS DISTINCT FROM design_content_pipeline.make_processing(a,i->'sourceBinding'->'source',i->>'requestId') THEN RAISE EXCEPTION 'CONTENT_PROCESSING_BINDING' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION design_content_pipeline.check_processing(a jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 PERFORM design_content_pipeline.assert_processing_binding(a,i);RETURN design_dependency_authority.digest(i);END$$;
CREATE FUNCTION design_content_pipeline.processing_permission(a jsonb,i jsonb) RETURNS design_normalization_processing.permissions LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_normalization_processing.permissions;BEGIN
 PERFORM design_content_pipeline.assert_processing_binding(a,i);SELECT * INTO STRICT p FROM design_normalization_processing.permissions x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=i->>'requestId' FOR SHARE;
 IF (p.authority IS DISTINCT FROM a OR p.intent IS DISTINCT FROM i OR NOT p.active OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;RETURN p;END$$;
CREATE FUNCTION design_content_pipeline.processing_claim_row(a jsonb,i jsonb) RETURNS design_normalization_processing.claims LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_normalization_processing.permissions;c design_normalization_processing.claims;BEGIN
 p:=design_content_pipeline.processing_permission(a,i);SELECT * INTO STRICT c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=i->>'requestId';
 IF (c.intent IS DISTINCT FROM i OR c.permission_id IS DISTINCT FROM p.id OR c.id IS DISTINCT FROM 'normalization-claim-'||design_dependency_authority.digest(i) OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;RETURN c;END$$;
CREATE FUNCTION design_content_pipeline.processing_prepare(token text,scope jsonb,sref jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE i jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;i:=design_content_pipeline.make_processing(design_content_pipeline.resolve(token,scope),sref,rid);PERFORM design_content_pipeline.assert_processing_binding(design_content_pipeline.resolve(token,scope),i);RETURN i;END$$;
CREATE FUNCTION design_content_pipeline.processing_authorize(token text,scope jsonb,i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM design_content_pipeline.processing_permission(design_content_pipeline.resolve(token,scope),i);PERFORM design_content_pipeline.processing_permission(design_content_pipeline.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.processing_guard(token text,scope jsonb,i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;PERFORM design_content_pipeline.processing_claim_row(design_content_pipeline.resolve(token,scope),i);PERFORM design_content_pipeline.processing_claim_row(design_content_pipeline.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.processing_claim(token text,scope jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_normalization_processing.permissions;c design_normalization_processing.claims;outcome text;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);p:=design_content_pipeline.processing_permission(a,i);SELECT * INTO c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=i->>'requestId';
 IF FOUND THEN PERFORM design_content_pipeline.processing_claim_row(a,i);outcome:='already_claimed';ELSE INSERT INTO design_normalization_processing.claims VALUES('normalization-claim-'||design_dependency_authority.digest(i),design_normalization_processing.owner_key(a),i->>'requestId',p.id,i);outcome:='created';END IF;
 PERFORM design_content_pipeline.processing_claim_row(design_content_pipeline.resolve(token,scope),i);RETURN outcome;END$$;
CREATE FUNCTION design_content_pipeline.processing_issue(token text,scope jsonb,pid text,i jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;k text;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalization_processing_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;
 a:=design_content_pipeline.resolve(token,scope);PERFORM design_content_pipeline.assert_processing_binding(a,i);k:=design_normalization_processing.owner_key(a);IF EXISTS(SELECT 1 FROM design_normalization_processing.claims x WHERE x.owner_key=k AND x.request_id=i->>'requestId') THEN RAISE EXCEPTION 'CONTENT_PROCESSING_CLAIMED';END IF;
 INSERT INTO design_normalization_processing.permissions VALUES(pid,k,i->>'requestId',a,i,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_content_pipeline.processing_permission(design_content_pipeline.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.check_artifact(a jsonb,i jsonb,n jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE out jsonb;expected jsonb;BEGIN
 PERFORM design_content_pipeline.assert_processing_binding(a,i);out:=n->'output';IF (NOT design_managed_image.exact(out,ARRAY['sha256','byteLength','mime','width','height']) OR jsonb_typeof(out->'sha256') IS DISTINCT FROM 'string' OR out->>'sha256'!~'^[a-f0-9]{64}$' OR jsonb_typeof(out->'byteLength') IS DISTINCT FROM 'number' OR out->>'byteLength'!~'^[1-9][0-9]{0,5}$' OR (out->>'byteLength')::int>262144 OR out->>'mime' IS DISTINCT FROM 'image/png' OR out->'width' IS DISTINCT FROM '80'::jsonb OR out->'height' IS DISTINCT FROM '120'::jsonb) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_PROCESSING_INVALID' USING ERRCODE='42501';END IF;
 expected:=jsonb_build_object('schemaVersion','design-application-normalization-artifact-v1','requestId',i->'requestId','authority',a,'sourceBinding',i->'sourceBinding','sourceManifest',i->'sourceManifest','normalizationPolicy',i->'policy','output',out,'state','pending_validation','submissionAuthorized',false,'adoptionAuthorized',false,'publicEligible',false);
 IF n IS DISTINCT FROM expected THEN RAISE EXCEPTION 'CONTENT_PROCESSING_BINDING' USING ERRCODE='42501';END IF;RETURN design_dependency_authority.digest(n);END$$;
CREATE FUNCTION design_content_pipeline.check_bound_content_v2(a jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c design_normalization_processing.claims;b design_normalization_processing.artifact_bindings;ad text;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));SELECT * INTO STRICT c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=rid;PERFORM design_content_pipeline.processing_claim_row(a,c.intent);SELECT * INTO STRICT b FROM design_normalization_processing.artifact_bindings x WHERE x.claim_id=c.id;ad:=design_content_pipeline.check_artifact(a,c.intent,b.artifact);
 IF b.artifact_digest IS DISTINCT FROM ad OR b.artifact->>'requestId' IS DISTINCT FROM rid THEN RAISE EXCEPTION 'CONTENT_PROCESSING_BINDING' USING ERRCODE='42501';END IF;PERFORM design_content_pipeline.processing_claim_row(a,c.intent);
 RETURN jsonb_build_object('schemaVersion','design-claimed-normalization-v2','artifact',b.artifact,'processingProvenance',jsonb_build_object('schemaVersion','design-normalization-processing-provenance-v2','claimId',c.id,'permissionId',c.permission_id,'intentDigest',design_dependency_authority.digest(c.intent),'artifactDigest',ad));END$$;
CREATE FUNCTION design_content_pipeline.processing_bind(token text,scope jsonb,i jsonb,n jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c design_normalization_processing.claims;b design_normalization_processing.artifact_bindings;ad text;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);c:=design_content_pipeline.processing_claim_row(a,i);ad:=design_content_pipeline.check_artifact(a,i,n);SELECT * INTO b FROM design_normalization_processing.artifact_bindings x WHERE x.claim_id=c.id;
 IF FOUND THEN IF b.artifact IS DISTINCT FROM n OR b.artifact_digest IS DISTINCT FROM ad THEN RAISE EXCEPTION 'CONTENT_PROCESSING_CONFLICT';END IF;ELSE INSERT INTO design_normalization_processing.artifact_bindings VALUES(c.id,ad,n);END IF;RETURN design_content_pipeline.check_bound_content_v2(design_content_pipeline.resolve(token,scope),i->>'requestId');END$$;
CREATE FUNCTION design_content_pipeline.processing_read_bound(token text,scope jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;v:=design_content_pipeline.check_bound_content_v2(design_content_pipeline.resolve(token,scope),rid);IF v IS DISTINCT FROM design_content_pipeline.check_bound_content_v2(design_content_pipeline.resolve(token,scope),rid) THEN RAISE EXCEPTION 'CONTENT_PROCESSING_CHANGED';END IF;RETURN v;END$$;
CREATE FUNCTION design_content_pipeline.processing_read_claim(token text,scope jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c design_normalization_processing.claims;b design_normalization_processing.artifact_bindings;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' OR rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_PROCESSING_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);SELECT * INTO c FROM design_normalization_processing.claims x WHERE x.owner_key=design_normalization_processing.owner_key(a) AND x.request_id=rid;IF NOT FOUND THEN IF design_content_pipeline.resolve(token,scope) IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_PROCESSING_CHANGED';END IF;RETURN NULL;END IF;
 PERFORM design_content_pipeline.processing_claim_row(a,c.intent);SELECT * INTO b FROM design_normalization_processing.artifact_bindings x WHERE x.claim_id=c.id;IF FOUND THEN PERFORM design_content_pipeline.check_bound_content_v2(a,rid);END IF;PERFORM design_content_pipeline.processing_claim_row(design_content_pipeline.resolve(token,scope),c.intent);RETURN jsonb_build_object('claimId',c.id,'permissionId',c.permission_id,'intentDigest',design_dependency_authority.digest(c.intent),'artifactDigest',b.artifact_digest);END$$;
-- Application derived writes use the SAME permission/reservation/claim/manifest
-- namespace. The old source-only fixed functions still reject this new schema.
CREATE FUNCTION design_content_pipeline.make_derived_intent(a jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE w jsonb;n jsonb;p jsonb;c jsonb;t jsonb;BEGIN
 w:=design_content_pipeline.check_bound_content_v2(a,rid);n:=w->'artifact';p:=w->'processingProvenance';c:=(n->'output')-ARRAY['width','height'];t:=n->'sourceManifest'->'target';
 RETURN jsonb_build_object('schemaVersion','application-content-write-intent-v2','authority',a,'requestId',rid,'assetId','canonical-'||(p->>'artifactDigest'),'role','canonical_png','expectedRevision',0,'expectedManifestDigest',null,'content',c,'target',jsonb_build_object('projectOrigin',t->'projectOrigin','bucket',t->'bucket','key','managed-content/v1/'||design_content_manifest.digest(a->'scope')||'/'||design_content_manifest.owner_key(a)||'/'||design_content_manifest.write_id(a,rid)||'/'||(c->>'sha256')),'ancestry',jsonb_build_object('source',n->'sourceBinding'->'source','parent',null),'processing',jsonb_build_object('kind','direct_png_normalization','requestId',rid,'intentDigest',p->'intentDigest','claimId',p->'claimId','artifactDigest',p->'artifactDigest'),'private',true,'storageSemantics','application_create_only_no_native_versions');END$$;
CREATE FUNCTION design_content_pipeline.derived_manifest(i jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT design_content_manifest.expected_manifest(i)||jsonb_build_object('schemaVersion','application-content-addressed-manifest-v2','manifestId','content-manifest-'||design_content_manifest.digest(jsonb_build_object('schemaVersion','application-content-addressed-manifest-v2','ownerNamespaceDigest',design_content_manifest.owner_key(i->'authority'),'scopeDigest',design_content_manifest.digest(i->'authority'->'scope'),'assetId',i->'assetId')))$$;
CREATE FUNCTION design_content_pipeline.check_derived_intent(a jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF i IS DISTINCT FROM design_content_pipeline.make_derived_intent(a,i->>'requestId') THEN RAISE EXCEPTION 'CONTENT_DERIVED_BINDING' USING ERRCODE='42501';END IF;RETURN design_content_manifest.digest(i);END$$;
CREATE FUNCTION design_content_pipeline.derived_permission(a jsonb,i jsonb) RETURNS design_content_manifest.permissions LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_content_manifest.permissions;BEGIN
 PERFORM design_content_pipeline.check_derived_intent(a,i);SELECT * INTO STRICT p FROM design_content_manifest.permissions x WHERE x.write_id=design_content_manifest.write_id(a,i->>'requestId') FOR SHARE;
 IF (p.intent IS DISTINCT FROM i OR NOT p.active OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN p;END$$;
CREATE FUNCTION design_content_pipeline.derived_context(a jsonb,rid text,access text DEFAULT 'write') RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE i jsonb;expected jsonb;r design_content_manifest.reservations;p design_content_manifest.permissions;c design_content_manifest.claims;m design_content_manifest.manifests;cid text;st text;source jsonb;BEGIN
 i:=design_content_pipeline.make_derived_intent(a,rid);expected:=design_content_pipeline.derived_manifest(i);SELECT * INTO STRICT r FROM design_content_manifest.reservations x WHERE x.write_id=design_content_manifest.write_id(a,rid);SELECT * INTO STRICT p FROM design_content_manifest.permissions x WHERE x.id=r.permission_id;
 IF (r.intent IS DISTINCT FROM i OR p.intent IS DISTINCT FROM i OR r.intent_digest IS DISTINCT FROM design_content_manifest.digest(i) OR r.manifest_id IS DISTINCT FROM expected->>'manifestId' OR r.expected_revision IS DISTINCT FROM 0 OR EXISTS(SELECT 1 FROM design_content_manifest.terminations x WHERE x.write_id=r.write_id)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED' USING ERRCODE='42501';END IF;
 cid:='content-claim-'||design_content_manifest.digest(jsonb_build_object('writeId',r.write_id,'intentDigest',r.intent_digest));SELECT * INTO c FROM design_content_manifest.claims x WHERE x.write_id=r.write_id;st:=CASE WHEN FOUND THEN 'claimed' ELSE 'reserved' END;IF c.claim_id IS NOT NULL AND c.claim_id IS DISTINCT FROM cid THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;
 SELECT * INTO m FROM design_content_manifest.manifests x WHERE x.write_id=r.write_id;
 IF FOUND THEN IF c.claim_id IS NULL OR m.record IS DISTINCT FROM expected OR m.digest IS DISTINCT FROM design_content_manifest.digest(expected) THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;st:='published';ELSIF EXISTS(SELECT 1 FROM design_content_manifest.manifests x WHERE x.manifest_id=r.manifest_id) THEN RAISE EXCEPTION 'CONTENT_HEAD_CHANGED';END IF;
 IF access='write' THEN PERFORM design_content_pipeline.derived_permission(a,i);ELSIF access='read' AND st='published' THEN PERFORM design_content_manifest.read_permission(a,m.record);ELSE RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;
 source:=design_content_pipeline.check_source(a,i->'ancestry'->'source');RETURN jsonb_build_object('intent',i,'previous',null,'ancestors',jsonb_build_array(source->'sourceManifest'),'claimedArtifact',design_content_pipeline.check_bound_content_v2(a,rid),'claimId',cid,'state',st,'manifest',m.record);END$$;
CREATE FUNCTION design_content_pipeline.derived_checked(a jsonb,rid text,idigest text,cid text,access text DEFAULT 'write') RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE ctx jsonb;BEGIN
 ctx:=design_content_pipeline.derived_context(a,rid,access);IF design_content_manifest.digest(ctx->'intent') IS DISTINCT FROM idigest OR ctx->>'claimId' IS DISTINCT FROM cid THEN RAISE EXCEPTION 'CONTENT_DERIVED_CONFLICT' USING ERRCODE='42501';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_pipeline.derived_reserve(token text,scope jsonb,i jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_content_manifest.permissions;r design_content_manifest.reservations;m jsonb;wid text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);p:=design_content_pipeline.derived_permission(a,i);wid:=design_content_manifest.write_id(a,i->>'requestId');m:=design_content_pipeline.derived_manifest(i);SELECT * INTO r FROM design_content_manifest.reservations x WHERE x.write_id=wid;
 IF FOUND THEN IF r.intent IS DISTINCT FROM i THEN RAISE EXCEPTION 'CONTENT_DERIVED_CONFLICT';END IF;ELSE IF EXISTS(SELECT 1 FROM design_content_manifest.manifests x WHERE x.manifest_id=m->>'manifestId') OR EXISTS(SELECT 1 FROM design_content_manifest.reservations x WHERE x.manifest_id=m->>'manifestId' AND NOT EXISTS(SELECT 1 FROM design_content_manifest.terminations t WHERE t.write_id=x.write_id)) THEN RAISE EXCEPTION 'CONTENT_HEAD_RESERVED';END IF;INSERT INTO design_content_manifest.reservations VALUES(wid,m->>'manifestId',0,i,design_content_manifest.digest(i),p.id);END IF;
 RETURN design_content_pipeline.derived_context(design_content_pipeline.resolve(token,scope),i->>'requestId');END$$;
CREATE FUNCTION design_content_pipeline.derived_claim(token text,scope jsonb,rid text,idigest text,cid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;ctx jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);ctx:=design_content_pipeline.derived_checked(a,rid,idigest,cid);IF ctx->>'state'<>'reserved' THEN RETURN '{"created":false}'::jsonb;END IF;
 INSERT INTO design_content_manifest.claims VALUES(design_content_manifest.write_id(a,rid),cid);PERFORM design_content_pipeline.derived_checked(design_content_pipeline.resolve(token,scope),rid,idigest,cid);RETURN '{"created":true}'::jsonb;END$$;
CREATE FUNCTION design_content_pipeline.derived_authorize(token text,scope jsonb,rid text,idigest text,cid text,phase text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;access text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' OR phase IS NULL OR phase NOT IN ('before_claim','before_put','before_read','before_publish','before_return','object_read_before','object_read_return') THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED' USING ERRCODE='42501';END IF;
 access:=CASE WHEN phase IN ('object_read_before','object_read_return') THEN 'read' ELSE 'write' END;ctx:=design_content_pipeline.derived_checked(design_content_pipeline.resolve(token,scope),rid,idigest,cid,access);
 IF phase IN ('before_put','before_read') AND ctx->>'state'<>'claimed' OR phase='before_publish' AND ctx->>'state'='reserved' THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;PERFORM design_content_pipeline.derived_checked(design_content_pipeline.resolve(token,scope),rid,idigest,cid,access);RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.derived_publish(token text,scope jsonb,rid text,idigest text,cid text,m jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;ctx jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_content_pipeline.resolve(token,scope);ctx:=design_content_pipeline.derived_checked(a,rid,idigest,cid);
 IF ctx->>'state'='reserved' OR m IS DISTINCT FROM design_content_pipeline.derived_manifest(ctx->'intent') THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;
 IF ctx->>'state'<>'published' THEN INSERT INTO design_content_manifest.manifests VALUES(m->>'manifestId',1,design_content_manifest.digest(m),design_content_manifest.write_id(a,rid),m);END IF;RETURN design_content_pipeline.derived_checked(design_content_pipeline.resolve(token,scope),rid,idigest,cid)->'manifest';END$$;
CREATE FUNCTION design_content_pipeline.check_derived(a jsonb,r jsonb,access text DEFAULT 'read') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE m design_content_manifest.manifests;ctx jsonb;BEGIN
 PERFORM design_content_pipeline.validate_ref(r);SELECT * INTO STRICT m FROM design_content_manifest.manifests x WHERE x.manifest_id=r->>'manifestId' AND x.revision=(r->>'revision')::int;
 IF design_content_pipeline.ref(m.record) IS DISTINCT FROM r OR m.digest IS DISTINCT FROM r->>'digest' OR m.record->'authority' IS DISTINCT FROM a OR m.record->>'role' IS DISTINCT FROM 'canonical_png' THEN RAISE EXCEPTION 'CONTENT_DERIVED_BINDING';END IF;ctx:=design_content_pipeline.derived_context(a,m.record->>'requestId',access);IF ctx->'manifest' IS DISTINCT FROM m.record THEN RAISE EXCEPTION 'CONTENT_DERIVED_BINDING';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_pipeline.derived_read(token text,scope jsonb,r jsonb,purpose text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;access text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' OR purpose IS NULL OR purpose NOT IN ('publication_receipt','object_read') THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;access:=CASE WHEN purpose='object_read' THEN 'read' ELSE 'write' END;ctx:=design_content_pipeline.check_derived(design_content_pipeline.resolve(token,scope),r,access);IF ctx IS DISTINCT FROM design_content_pipeline.check_derived(design_content_pipeline.resolve(token,scope),r,access) THEN RAISE EXCEPTION 'CONTENT_DERIVED_CHANGED';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_pipeline.derived_reconcile(token text,scope jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;ctx jsonb;access text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;a:=design_content_pipeline.resolve(token,scope);access:=CASE WHEN EXISTS(SELECT 1 FROM design_content_manifest.manifests x WHERE x.write_id=design_content_manifest.write_id(a,rid)) THEN 'read' ELSE 'write' END;ctx:=design_content_pipeline.derived_context(a,rid,access);IF ctx IS DISTINCT FROM design_content_pipeline.derived_context(design_content_pipeline.resolve(token,scope),rid,access) THEN RAISE EXCEPTION 'CONTENT_DERIVED_CHANGED';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_pipeline.derived_receipt(token text,scope jsonb,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;ctx:=design_content_pipeline.derived_context(design_content_pipeline.resolve(token,scope),rid);IF ctx IS DISTINCT FROM design_content_pipeline.derived_context(design_content_pipeline.resolve(token,scope),rid) THEN RAISE EXCEPTION 'CONTENT_DERIVED_CHANGED';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_pipeline.derived_issue(token text,scope jsonb,pid text,i jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;BEGIN
 IF (session_user IS DISTINCT FROM 'design_content_storage_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_DERIVED_DENIED';END IF;a:=design_content_pipeline.resolve(token,scope);PERFORM design_content_pipeline.check_derived_intent(a,i);
 INSERT INTO design_content_manifest.permissions VALUES(pid,design_content_manifest.write_id(a,i->>'requestId'),i,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_content_pipeline.derived_permission(design_content_pipeline.resolve(token,scope),i);RETURN true;END$$;
-- Same canonical task/report tables and independent existing issuer identities.
CREATE FUNCTION design_content_pipeline.make_task(a jsonb,tid text,rid text,nref jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE w jsonb;n jsonb;c design_content_pipeline.config;BEGIN
 IF tid IS NULL OR tid!~'^[A-Za-z0-9_-]{1,100}$' OR rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_CANONICAL_INVALID';END IF;
 w:=design_content_pipeline.check_bound_content_v2(a,rid);n:=design_content_pipeline.check_derived(a,nref)->'manifest';SELECT * INTO STRICT c FROM design_content_pipeline.config WHERE singleton;
 IF n->>'requestId' IS DISTINCT FROM rid OR n->'processing'->>'artifactDigest' IS DISTINCT FROM w->'processingProvenance'->>'artifactDigest' THEN RAISE EXCEPTION 'CONTENT_CANONICAL_BINDING';END IF;
 RETURN jsonb_build_object('schemaVersion','design-normalized-strict-task-v2','taskId',tid,'claimedArtifact',w,'normalizedManifest',n,'fixtureId',c.policy->'fixture'->'id','verifier',c.verifier,'policy',c.policy);END$$;
CREATE FUNCTION design_content_pipeline.task_context(a jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE t design_canonical_verification.tasks;c jsonb;BEGIN
 SELECT * INTO STRICT t FROM design_canonical_verification.tasks x WHERE x.id=tid FOR SHARE;IF (NOT t.active OR t.authority IS DISTINCT FROM a OR t.expires_at<=clock_timestamp() OR t.task->>'schemaVersion' IS DISTINCT FROM 'design-normalized-strict-task-v2') IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;
 c:=design_content_pipeline.make_task(a,tid,t.request_id,design_content_pipeline.ref(t.task->'normalizedManifest'));IF c IS DISTINCT FROM t.task OR t.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN c;END$$;
CREATE FUNCTION design_content_pipeline.task_binding(t jsonb) RETURNS jsonb LANGUAGE sql SET search_path=pg_catalog AS $$SELECT jsonb_build_object('schemaVersion','design-normalized-strict-binding-v2','taskId',t->'taskId','taskDigest',design_dependency_authority.digest(t),'authority',t->'claimedArtifact'->'artifact'->'authority','scope',t->'claimedArtifact'->'artifact'->'authority'->'scope','sourceBinding',t->'claimedArtifact'->'artifact'->'sourceBinding','sourceBindingDigest',design_dependency_authority.digest(t->'claimedArtifact'->'artifact'->'sourceBinding'),'sourceReference',t->'claimedArtifact'->'artifact'->'sourceBinding'->'source','sourceContent',t->'claimedArtifact'->'artifact'->'sourceManifest'->'content','normalizedReference',design_content_pipeline.ref(t->'normalizedManifest'),'normalizedContent',t->'normalizedManifest'->'content','artifactDigest',design_dependency_authority.digest(t->'claimedArtifact'->'artifact'),'claimedArtifactDigest',design_dependency_authority.digest(t->'claimedArtifact'),'processingProvenance',t->'claimedArtifact'->'processingProvenance','processingProvenanceDigest',design_dependency_authority.digest(t->'claimedArtifact'->'processingProvenance'),'verifier',t->'verifier','policy',t->'policy','policyDigest',design_dependency_authority.digest(t->'policy'),'fixture',t->'policy'->'fixture','output',t->'claimedArtifact'->'artifact'->'output')$$;
CREATE FUNCTION design_content_pipeline.check_report(t jsonb,r jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE b jsonb;c jsonb;st text;e jsonb;expected jsonb;BEGIN
 b:=design_content_pipeline.task_binding(t);c:=r->'checks';IF (NOT design_managed_image.exact(c,ARRAY['fixturePngComplete','sourceExactFixtureProducerMatch','normalizedPngComplete','normalizedPixelsEqual','metadataAbsent','identityOrientation','sameGeometry']) OR EXISTS(SELECT 1 FROM jsonb_each(c) x WHERE x.value NOT IN ('"unknown"'::jsonb,'"failed"'::jsonb,'"verified"'::jsonb))) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_CANONICAL_REPORT_INVALID';END IF;
 st:=CASE WHEN EXISTS(SELECT 1 FROM jsonb_each_text(c) x WHERE x.value='failed') THEN 'validation_failed' WHEN EXISTS(SELECT 1 FROM jsonb_each_text(c) x WHERE x.value='unknown') THEN 'pending_validation' ELSE 'evidence_complete' END;
 e:=CASE WHEN st='evidence_complete' THEN jsonb_build_object('schemaVersion','design-normalized-strict-evidence-v2','id','strict-application-verification-'||design_dependency_authority.digest(jsonb_build_object('binding',b,'checks',c)),'taskDigest',b->>'taskDigest','verificationBindingDigest',design_dependency_authority.digest(b),'policyDigest',b->>'policyDigest','verifier',t->'verifier','checks',c) ELSE 'null'::jsonb END;
 expected:=jsonb_build_object('schemaVersion','design-normalized-strict-report-v2','taskDigest',b->>'taskDigest','verificationBinding',b,'checks',c,'state',st,'evidence',e,'submissionAuthorized',false,'adoptionAuthorized',false,'publicEligible',false);
 IF r IS DISTINCT FROM expected THEN RAISE EXCEPTION 'CONTENT_CANONICAL_REPORT_INVALID';END IF;RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.canonical_issue_task(token text,scope jsonb,tid text,rid text,nref jsonb,ttl bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;t jsonb;BEGIN
 IF (session_user IS DISTINCT FROM 'design_canonical_authorizer' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;a:=design_content_pipeline.resolve(token,scope);t:=design_content_pipeline.make_task(a,tid,rid,nref);INSERT INTO design_canonical_verification.tasks VALUES(tid,a,rid,t,clock_timestamp()+ttl*interval '1 millisecond',true);RETURN design_content_pipeline.task_context(design_content_pipeline.resolve(token,scope),tid);END$$;
CREATE FUNCTION design_content_pipeline.canonical_read_task(token text,scope jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_canonical_verifier' THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;t:=design_content_pipeline.task_context(design_content_pipeline.resolve(token,scope),tid);IF t IS DISTINCT FROM design_content_pipeline.task_context(design_content_pipeline.resolve(token,scope),tid) THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN t;END$$;
CREATE FUNCTION design_content_pipeline.canonical_guard_task(token text,scope jsonb,tid text,td text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t jsonb;BEGIN
 t:=design_content_pipeline.canonical_read_task(token,scope,tid);IF td IS DISTINCT FROM design_dependency_authority.digest(t) THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN true;END$$;
CREATE FUNCTION design_content_pipeline.canonical_publish(token text,scope jsonb,tid text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t jsonb;old design_canonical_verification.reports;BEGIN
 IF session_user IS DISTINCT FROM 'design_canonical_verifier' THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;t:=design_content_pipeline.task_context(design_content_pipeline.resolve(token,scope),tid);PERFORM design_content_pipeline.check_report(t,r);SELECT * INTO old FROM design_canonical_verification.reports x WHERE x.task_id=tid;
 IF FOUND THEN IF NOT old.active OR old.report IS DISTINCT FROM r THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CONFLICT';END IF;ELSE INSERT INTO design_canonical_verification.reports VALUES(tid,r,true);END IF;t:=design_content_pipeline.task_context(design_content_pipeline.resolve(token,scope),tid);PERFORM design_content_pipeline.check_report(t,r);RETURN jsonb_build_object('task',t,'report',r);END$$;
CREATE FUNCTION design_content_pipeline.check_status_content_v2(a jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t jsonb;r design_canonical_verification.reports;BEGIN
 t:=design_content_pipeline.task_context(a,tid);SELECT * INTO STRICT r FROM design_canonical_verification.reports x WHERE x.task_id=tid FOR SHARE;IF NOT r.active THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;PERFORM design_content_pipeline.check_report(t,r.report);IF t IS DISTINCT FROM design_content_pipeline.task_context(a,tid) THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN jsonb_build_object('task',t,'report',r.report);END$$;
CREATE FUNCTION design_content_pipeline.check_verified_content_v2(a jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE p jsonb;BEGIN
 p:=design_content_pipeline.check_status_content_v2(a,tid);IF p->'report'->>'state' IS DISTINCT FROM 'evidence_complete' THEN RAISE EXCEPTION 'CONTENT_CANONICAL_NOT_VERIFIED';END IF;RETURN p;END$$;
CREATE FUNCTION design_content_pipeline.canonical_read_status(token text,scope jsonb,tid text,verified boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p jsonb;last jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' OR verified IS NULL THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;a:=design_content_pipeline.resolve(token,scope);p:=CASE WHEN verified THEN design_content_pipeline.check_verified_content_v2(a,tid) ELSE design_content_pipeline.check_status_content_v2(a,tid) END;
 a:=design_content_pipeline.resolve(token,scope);last:=CASE WHEN verified THEN design_content_pipeline.check_verified_content_v2(a,tid) ELSE design_content_pipeline.check_status_content_v2(a,tid) END;IF p IS DISTINCT FROM last THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN p;END$$;
CREATE FUNCTION design_content_pipeline.content_read_kind(token text,scope jsonb,r jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;m design_content_manifest.manifests;kind text;BEGIN
 IF session_user IS DISTINCT FROM 'design_identity_runtime' THEN RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED';END IF;a:=design_content_pipeline.resolve(token,scope);PERFORM design_content_pipeline.validate_ref(r);SELECT * INTO STRICT m FROM design_content_manifest.manifests x WHERE x.manifest_id=r->>'manifestId' AND x.revision=(r->>'revision')::int;
 kind:=m.record->>'role';IF kind='source' THEN PERFORM design_content_pipeline.check_source(a,r);ELSIF kind='canonical_png' THEN PERFORM design_content_pipeline.check_derived(a,r);ELSE RAISE EXCEPTION 'CONTENT_PIPELINE_DENIED';END IF;
 a:=design_content_pipeline.resolve(token,scope);IF kind='source' THEN PERFORM design_content_pipeline.check_source(a,r);ELSE PERFORM design_content_pipeline.check_derived(a,r);END IF;RETURN kind;END$$;
CREATE FUNCTION design_content_pipeline.canonical_query_status(token text,scope jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;t jsonb;r design_canonical_verification.reports;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' OR tid IS NULL OR tid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;a:=design_content_pipeline.resolve(token,scope);
 IF NOT EXISTS(SELECT 1 FROM design_canonical_verification.tasks x WHERE x.id=tid) THEN IF design_content_pipeline.resolve(token,scope) IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN NULL;END IF;
 t:=design_content_pipeline.task_context(a,tid);SELECT * INTO r FROM design_canonical_verification.reports x WHERE x.task_id=tid FOR SHARE;IF FOUND THEN IF NOT r.active THEN RAISE EXCEPTION 'CONTENT_CANONICAL_DENIED';END IF;PERFORM design_content_pipeline.check_report(t,r.report);END IF;
 IF t IS DISTINCT FROM design_content_pipeline.task_context(design_content_pipeline.resolve(token,scope),tid) THEN RAISE EXCEPTION 'CONTENT_CANONICAL_CHANGED';END IF;RETURN jsonb_build_object('task',t,'report',r.report);END$$;
-- Assign function owners by capability domain. No new LOGIN or broad table grant.
DO $$DECLARE f record;owner_role text;BEGIN FOR f IN SELECT p.oid::regprocedure sig,p.proname FROM pg_proc p WHERE p.pronamespace='design_content_pipeline'::regnamespace LOOP
 owner_role:=CASE WHEN f.proname IN ('make_processing','check_processing','assert_processing_binding','processing_permission','processing_claim_row','processing_prepare','processing_authorize','processing_guard','processing_claim','processing_issue','check_artifact','check_bound_content_v2','processing_bind','processing_read_bound','processing_read_claim','make_task','task_context','task_binding','check_report','canonical_issue_task','canonical_read_task','canonical_guard_task','canonical_publish','check_status_content_v2','check_verified_content_v2','canonical_read_status','canonical_query_status') THEN 'design_managed_image_capability' ELSE 'design_content_capability' END;
 EXECUTE format('ALTER FUNCTION %s OWNER TO %I',f.sig,owner_role);
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_identity_runtime,design_normalization_runtime,design_normalization_processing_issuer,design_canonical_authorizer,design_canonical_verifier,design_content_storage_issuer',f.sig);END LOOP;END$$;
-- Cross-domain cooperation is only through these fixed private authority-bound
-- functions. Neither LOGIN receives table access or these helper capabilities.
GRANT EXECUTE ON FUNCTION design_content_pipeline.resolve(text,jsonb),design_content_pipeline.ref(jsonb),design_content_pipeline.check_source(jsonb,jsonb),design_content_pipeline.check_derived(jsonb,jsonb,text) TO design_managed_image_capability;
GRANT EXECUTE ON FUNCTION design_content_pipeline.check_bound_content_v2(jsonb,text) TO design_content_capability;
GRANT EXECUTE ON FUNCTION design_content_pipeline.prepare_upload(text,jsonb,text,text,text,text,jsonb),design_content_pipeline.reserve_upload(text,jsonb,jsonb,jsonb),design_content_pipeline.read_source(text,jsonb,jsonb),design_content_pipeline.upload_status(text,jsonb,text,text) TO design_identity_runtime;
GRANT EXECUTE ON FUNCTION design_content_pipeline.derived_reserve(text,jsonb,jsonb),design_content_pipeline.derived_claim(text,jsonb,text,text,text),design_content_pipeline.derived_authorize(text,jsonb,text,text,text,text),design_content_pipeline.derived_publish(text,jsonb,text,text,text,jsonb),design_content_pipeline.derived_read(text,jsonb,jsonb,text),design_content_pipeline.derived_reconcile(text,jsonb,text),design_content_pipeline.derived_receipt(text,jsonb,text) TO design_identity_runtime;
GRANT EXECUTE ON FUNCTION design_content_pipeline.derived_issue(text,jsonb,text,jsonb,bigint) TO design_content_storage_issuer;
GRANT EXECUTE ON FUNCTION design_content_pipeline.processing_prepare(text,jsonb,jsonb,text),design_content_pipeline.processing_authorize(text,jsonb,jsonb),design_content_pipeline.processing_claim(text,jsonb,jsonb),design_content_pipeline.processing_guard(text,jsonb,jsonb),design_content_pipeline.processing_bind(text,jsonb,jsonb,jsonb),design_content_pipeline.processing_read_bound(text,jsonb,text),design_content_pipeline.processing_read_claim(text,jsonb,text) TO design_normalization_runtime;
GRANT EXECUTE ON FUNCTION design_content_pipeline.processing_issue(text,jsonb,text,jsonb,bigint) TO design_normalization_processing_issuer;
GRANT EXECUTE ON FUNCTION design_content_pipeline.canonical_issue_task(text,jsonb,text,text,jsonb,bigint) TO design_canonical_authorizer;
GRANT EXECUTE ON FUNCTION design_content_pipeline.canonical_read_task(text,jsonb,text),design_content_pipeline.canonical_guard_task(text,jsonb,text,text),design_content_pipeline.canonical_publish(text,jsonb,text,jsonb) TO design_canonical_verifier;
GRANT EXECUTE ON FUNCTION design_content_pipeline.canonical_read_status(text,jsonb,text,boolean) TO design_normalization_runtime;
REVOKE CREATE ON SCHEMA design_content_pipeline FROM design_content_capability,design_managed_image_capability;
REVOKE ALL ON ALL TABLES IN SCHEMA design_content_pipeline FROM PUBLIC,anon,authenticated,design_identity_runtime,design_normalization_runtime,design_normalization_processing_issuer,design_canonical_authorizer,design_canonical_verifier,design_content_storage_issuer;

GRANT EXECUTE ON FUNCTION design_content_pipeline.content_read_kind(text,jsonb,jsonb) TO design_identity_runtime;

GRANT EXECUTE ON FUNCTION design_content_pipeline.canonical_query_status(text,jsonb,text) TO design_normalization_runtime;
